def simplify_res(res):
    thres=64*round_num
    f_res=[]
    for l1 in res:
        tmp=[]
        for i in l1:
            if(i<thres):
                tmp.append(i)
        if(tmp in f_res):
            pass
        else:
            f_res.append(tmp.copy())
    return f_res
